<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans, sans-serif;color:#173b72;font-size:11px}h1{margin:0;color:#173b72;font-size:22px}p{color:#64748b;margin:5px 0 18px}table{width:100%;border-collapse:collapse}th{background:#243dba;color:#fff;text-align:left;padding:9px}td{border:1px solid #cbd5e1;padding:8px}tr:nth-child(even){background:#f1f5fb}.right{text-align:right}.status{font-weight:bold}</style></head><body><h1>VAT Stock Report</h1><p>Firm: {{ $firm->name }} | Generated: {{ now()->format('Y-m-d H:i') }}</p><table><thead><tr><th>Item</th><th>Unit</th><th class="right">Available</th><th class="right">Purchase Rate</th><th class="right">Sale Rate</th><th class="right">Reorder Level</th><th>Status</th></tr></thead><tbody>@foreach($stocks as $stock)<tr><td>{{ $stock->item_name }}</td><td>{{ $stock->unit }}</td><td class="right">{{ number_format($stock->quantity,3) }}</td><td class="right">Rs {{ number_format($stock->purchase_rate,2) }}</td><td class="right">Rs {{ number_format($stock->sale_rate,2) }}</td><td class="right">{{ number_format($stock->reorder_level,3) }}</td><td class="status">{{ $stock->quantity<=0?'Out of stock':($stock->reorder_level>0&&$stock->quantity<=$stock->reorder_level?'Low stock':'In stock') }}</td></tr>@endforeach</tbody></table></body></html>
